function saveAndMaterial(id,tool){if(commitLine({preventDefault(){}},id)===false)return;if(tool==='units')sheetDialog(id);else estimateDialog(id)}
function materialToolsHTML(l){return l.kind==='material'?`<div class="mini-actions"><button type="button" onclick="saveAndMaterial('${l.id}','units')">Лист ↔ м²</button><button type="button" onclick="saveAndMaterial('${l.id}','estimate')">Оценить по ₽/кг</button></div>${l.estimate?'<div class="note">Предварительная оценка по массе. Требует проверки по предложению поставщика.</div>':''}`:''}
function sheetDialog(id){const l=state.lines.find(l=>l.id===id);if(!l)return;const dims=MaterialCore.sheetSize(l,CATALOG.find(c=>c.id===l.catalogId));modal('Единицы листового материала',`<h3>${esc(l.name)}</h3><p class="small">Сейчас: ${money(l.price)} / ${esc(MaterialCore.unitLabel(l.unit))}. Размеры — в метрах. ${esc(dims?.source||'Введите фактический формат листа.')}</p><div class="grid2"><div class="field"><label for="sheetWidth">Ширина листа, м</label><input id="sheetWidth" type="number" min="0" step="any" value="${dims?.width??''}" oninput="sheetPreview('${id}')"></div><div class="field"><label for="sheetLength">Длина листа, м</label><input id="sheetLength" type="number" min="0" step="any" value="${dims?.length??''}" oninput="sheetPreview('${id}')"></div></div><div class="field"><label for="sheetUnit">Единица объёма и цены</label><select id="sheetUnit" onchange="sheetPreview('${id}')"><option value="м²">м²</option><option value="шт.">Листы, шт.</option></select></div><label class="checkrow"><input id="sheetWhole" type="checkbox" checked onchange="sheetPreview('${id}')">Закупать целыми листами (площадь округляется до площади целого листа)</label><div class="note info" id="sheetPreview"></div><p class="small">Пересчитываются объём, цена, масса единицы и закупочная кратность. Запас остаётся прежним. Раскрой не выполняется. Остатки в других единицах автоматически не объединяются.</p><div class="mini-actions"><button class="primary" onclick="applySheet('${id}')">Применить пересчёт</button><button onclick="editLine('${id}')">Назад</button></div>`);sheetPreview(id)}
function sheetCandidate(id){return MaterialCore.convertSheet(state.lines.find(l=>l.id===id),+$('sheetWidth').value,+$('sheetLength').value,$('sheetUnit').value,$('sheetWhole').checked)}
function sheetPreview(id){try{const l=sheetCandidate(id);$('sheetPreview').textContent='Площадь листа: '+dec(l.sheetWidth*l.sheetLength)+' м² · новая цена: '+money(l.price)+' / '+l.unit+' · объём: '+dec(l.qty)+' · кратность: '+dec(l.pack)+' '+l.unit;}catch(e){$('sheetPreview').textContent=e.message}}
function applySheet(id){try{const l=sheetCandidate(id);Object.assign(state.lines.find(l=>l.id===id),l);persist();editLine(id);toast('Единицы пересчитаны. Проверьте объём и закупочную кратность')}catch(e){toast(e.message)}}
function estimateDialog(id){const l=state.lines.find(l=>l.id===id);if(!l)return;modal('Предварительная цена по массе',`<h3>${esc(l.name)}</h3><p class="small">Цена одной ${esc(MaterialCore.unitLabel(l.unit))} = масса этой единицы × ставка за кг с НДС. Ставка зависит от марки, формы проката и обработки. Общей цены для всей нержавейки нет.</p><div class="field"><label for="estimateGrade">Вид / марка стали</label><input id="estimateGrade" value="${esc(l.estimate?.grade||'')}" placeholder="Углеродистая сталь, AISI 304, AISI 316…"></div><div class="grid2"><div class="field"><label for="estimateMass">Масса одной ${esc(MaterialCore.unitLabel(l.unit))}, кг</label><input id="estimateMass" type="number" min="0" step="any" value="${l.mass??''}" oninput="estimatePreview('${id}')"></div><div class="field"><label for="estimateRate">Ставка с НДС, ₽/кг</label><input id="estimateRate" type="number" min="0" step="any" value="${l.estimate?.rate??''}" oninput="estimatePreview('${id}')"></div></div><div class="field"><label for="estimateNote">Основание ставки и массы</label><input id="estimateNote" value="${esc(l.estimate?.note||'')}" placeholder="Счёт, аналог, расчёт массы, дата…"></div><div class="note info" id="estimatePreview"></div><div class="field"><label for="referenceGrade">Ориентиры из библиотеки — выбор аналога вручную</label><select id="referenceGrade" onchange="estimateReferences()"><option value="carbon">Углеродистая сталь · прайс СтальГрад</option><option value="09Г2С">Углеродистая 09Г2С · прайс СтальГрад</option><option value="304">Нержавеющая AISI 304 · прежняя библиотека</option><option value="316">Нержавеющая AISI 316 · прежняя библиотека</option></select></div><p class="small">Ориентиры вычисляются как цена / масса в одной единице. Это цены проката, включающие его форму и обработку, а не биржевая стоимость металла. Проверяйте дату и сопоставимость. Выбор не меняет наименование материала.</p><div class="catalog-results" id="estimateReferences"></div><label class="checkrow"><input id="estimateConfirm" type="checkbox">Понимаю, что это предварительная оценка; масса и ставка относятся к указанной единице и марке</label><div class="mini-actions"><button class="primary" onclick="applyEstimate('${id}')">Применить оценку</button><button onclick="editLine('${id}')">Назад</button></div>`);estimateReferences();estimatePreview(id)}
function estimatePreview(id){const mass=+$('estimateMass').value,rate=+$('estimateRate').value,l=state.lines.find(l=>l.id===id);$('estimatePreview').textContent=mass>0&&rate>0?'Расчётная цена: '+money(mass*rate)+' / '+l.unit:'Укажите положительные массу единицы и ставку за кг'}
function estimateReferences(){const a=MaterialCore.references(CATALOG,$('referenceGrade').value),t=MaterialCore.stats(a);$('estimateReferences').innerHTML=a.length?`<div class="note info">${t.count} листов · ${money(t.min)}–${money(t.max)} / кг · медиана <b>${money(t.median)} / кг</b><br><button type="button" onclick="useMedianRate()">Использовать медиану</button></div><p class="small">Одинаковые ставки могут происходить из одной исходной калькуляции. Это проверка согласованности библиотеки, а не независимые рыночные котировки. Для AISI 304 дата исходных цен может отсутствовать.</p><table><thead><tr><th>Лист</th><th>Цена листа</th><th>Масса листа, кг</th><th>₽/кг</th><th>Дата</th><th></th></tr></thead><tbody>${a.map(c=>`<tr><td>${esc(c.name)}</td><td>${money(c.sheetPrice)}</td><td>${dec(c.sheetMass)}</td><td>${money(c.rate)}</td><td>${esc(c.date)}</td><td><button type="button" onclick="chooseEstimateReference('${c.id}')">Выбрать</button></td></tr>`).join('')}</tbody></table>`:'<p class="small">Подходящих числовых ориентиров нет. Введите подтверждённую ставку вручную.</p>'}
function useMedianRate(){const grade=$('referenceGrade').value,a=MaterialCore.references(CATALOG,grade),t=MaterialCore.stats(a);if(!t.count)return;$('estimateRate').value=t.median;$('estimateGrade').value=grade==='carbon'?'Углеродистая сталь':grade==='09Г2С'?'09Г2С':'AISI '+grade;$('estimateNote').value='Медиана по '+t.count+' листам библиотеки; диапазон '+t.min+'–'+t.max+' ₽/кг; источники: '+a.map(c=>c.id+' ('+c.date+')').join(', ');$('estimatePreview').textContent='Медиана '+money(t.median)+' ₽/кг. Проверьте массу вашей единицы и сопоставимость марки.'}
function chooseEstimateReference(id){const c=CATALOG.find(c=>c.id===id);if(!c||!(c.mass>0&&c.price>0))return;$('estimateRate').value=c.price/c.mass;$('estimateNote').value='Аналог: '+c.name+' · '+(c.date||'дата не указана')+' · '+(c.purchaseSource||c.book+' '+c.sheet+'!'+c.priceCell);$('estimateGrade').value=$('referenceGrade').value==='carbon'?'Углеродистая сталь':$('referenceGrade').value==='09Г2С'?'09Г2С':$('referenceGrade').value==='304'?'AISI 304':'AISI 316';$('estimatePreview').textContent='Ставка аналога: '+money(c.price/c.mass)+' ₽/кг. Проверьте массу вашей единицы и сопоставимость марки.'}
function applyEstimate(id){if(!$('estimateConfirm').checked){toast('Подтвердите предварительный характер оценки');return}try{const l=state.lines.find(l=>l.id===id),v=MaterialCore.estimate(l,+$('estimateMass').value,+$('estimateRate').value,$('estimateGrade').value,$('estimateNote').value);v.date=today();Object.assign(l,v);persist();editLine(id);toast('Применена предварительная оценка по массе')}catch(e){toast(e.message)}}
